extensionAttribute.scriptContentsMac:
#!/bin/zsh
# Updated by SecurityShrimp 2026 # Content Caching Service Status Extension Attribute # Targets macOS 12 through 26 (Tahoe), Intel and Apple Silicon # macOS Server (Server.app) was discontinued in 2022; the Content Caching # service is now built into base macOS and controlled via the Sharing # preference pane / AssetCacheManagerUtil. The legacy serveradmin command # no longer exists on modern macOS.
if /usr/bin/AssetCacheManagerUtil status 2>/dev/null | /usr/bin/grep -q "Activated: true"; then echo "<result>RUNNING</result>" else echo "<result>STOPPED</result>" fi
